    cutOff = 0;
    /* count near zeros on the right */
    for (j = filter2Size - 1; j > 0; j--) {
        cutOff += FFABS(filter2[i * filter2Size + j]);

        if (cutOff > SWS_MAX_REDUCE_CUTOFF * fone)
