           "SwScaler: reducing / aligning filtersize %d -> %d\n",
           filter2Size, filterSize);
/* try to reduce the filter-size (step2 reduce it) */
for (i = 0; i < dstW; i++) {
    int j;

    for (j = 0; j < filterSize; j++) {
        if (j >= filter2Size)
            filter[i * filterSize + j] = 0;
